type ThrottleOptions = {
  maxPerWindow: number;
  windowMs: number;
};

export function throttle<T extends (...args: any[]) => any>(
  fn: T,
  options: ThrottleOptions,
): (...args: Parameters<T>) => void {
  let lastCall = 0;
  let countInWindow = 0;

  return (...args: Parameters<T>) => {
    const now = Date.now();
    const window = options.windowMs;
    const max = options.maxPerWindow;

